import React, { useEffect, useState } from 'react';
import './LastVisited.css';

const LastVisited = () => {
    const [lastData, setLastData] = useState(null);
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        // 1. Get the data from the previous visit
        const savedData = localStorage.getItem('userLastVisit');
        const currentPath = window.location.pathname;

        if (savedData) {
            const parsedData = JSON.parse(savedData);
            // Only show the popup if the last visited page is different from current
            if (parsedData.path !== currentPath) {
                setLastData(parsedData);
                setIsVisible(true);
            }
        }

        // 2. Save the current visit details for next time
        const visitDetails = {
            path: currentPath,
            time: new Date().toLocaleString([], { 
                month: 'long', 
                day: 'numeric', 
                year: 'numeric', 
                hour: '2-digit', 
                minute: '2-digit' 
            })
        };
        localStorage.setItem('userLastVisit', JSON.stringify(visitDetails));
    }, []);

    if (!isVisible || !lastData) return null;

    return (
        <div className="lv-container">
            <div className="lv-header">
                <span>Last visited {lastData.time}</span>
                <button className="lv-close" onClick={() => setIsVisible(false)}>×</button>
            </div>
            <div className="lv-body">
                <a href={lastData.path} className="lv-link">Go to Last Visited Page</a>
            </div>
        </div>
    );
};

export default LastVisited;
